# Author: Kevin Ngo, 5/30/26 - enhanced signal history system
# Stores and manages BUY/SELL/HOLD recommendations generated by
# Macropulse trading strategies for historical analysis.

from collections import defaultdict
from datetime import datetime, timezone


# Kevin Ngo, 5/30/26 - stores signal history grouped by stock symbol
_history = defaultdict(list)


# Kevin Ngo, 5/30/26 - maximum number of records stored per symbol
MAX_HISTORY_PER_SYMBOL = 50


# Kevin Ngo, 5/30/26 - valid signal types accepted by Macropulse
VALID_SIGNALS = {"BUY", "SELL", "HOLD"}


def _normalize_symbol(symbol):
    # Kevin Ngo, 5/30/26 - standardize stock symbol formatting
    return str(symbol).upper().strip()


def _validate_signal(signal):
    # Kevin Ngo, 5/30/26 - validate recommendation type

    signal = str(signal).upper().strip()

    if signal not in VALID_SIGNALS:
        raise ValueError(f"Invalid signal type: {signal}")

    return signal


def _normalize_confidence(confidence):
    # Kevin Ngo, 5/30/26 - safely convert confidence score

    try:
        confidence = float(confidence)
    except (TypeError, ValueError):
        confidence = 0.0

    confidence = max(0.0, min(confidence, 100.0))

    return round(confidence, 2)


def _create_signal_entry(signal, confidence, strategy=None):
    # Kevin Ngo, 5/30/26 - create standardized history entry

    return {
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "signal": signal,
        "confidence": confidence,
        "strategy": strategy or "Unknown",
    }


def _trim_history(symbol):
    # Kevin Ngo, 5/30/26 - enforce maximum storage size

    if len(_history[symbol]) > MAX_HISTORY_PER_SYMBOL:
        _history[symbol] = _history[symbol][-MAX_HISTORY_PER_SYMBOL:]


def record_signal(symbol, signal_data):
    # Kevin Ngo, 5/30/26 - store a new trading recommendation

    normalized_symbol = _normalize_symbol(symbol)

    signal = _validate_signal(
        signal_data.get("signal", "")
    )

    confidence = _normalize_confidence(
        signal_data.get("confidence", 0)
    )

    strategy = signal_data.get("strategy")

    entry = _create_signal_entry(
        signal,
        confidence,
        strategy
    )

    _history[normalized_symbol].append(entry)

    _trim_history(normalized_symbol)

    return entry


def get_history(symbol):
    # Kevin Ngo, 5/30/26 - retrieve history for one stock

    normalized_symbol = _normalize_symbol(symbol)

    return list(_history.get(normalized_symbol, []))


def get_latest_signal(symbol):
    # Kevin Ngo, 5/30/26 - return most recent recommendation

    normalized_symbol = _normalize_symbol(symbol)

    history = _history.get(normalized_symbol, [])

    if not history:
        return None

    return history[-1]


def clear_history(symbol=None):
    # Kevin Ngo, 5/30/26 - clear stored history

    if symbol is not None:
        normalized_symbol = _normalize_symbol(symbol)
        _history.pop(normalized_symbol, None)
        return

    _history.clear()


def get_total_symbols_tracked():
    # Kevin Ngo, 5/30/26 - return number of tracked symbols

    return len(_history)


def get_total_signal_count(symbol=None):
    # Kevin Ngo, 5/30/26 - return number of stored signals

    if symbol is not None:
        normalized_symbol = _normalize_symbol(symbol)
        return len(_history.get(normalized_symbol, []))

    return sum(len(entries) for entries in _history.values())


def get_signal_breakdown(symbol):
    # Kevin Ngo, 5/30/26 - count BUY, SELL, and HOLD signals
    # recorded for a specific stock

    normalized_symbol = _normalize_symbol(symbol)

    breakdown = {
        "BUY": 0,
        "SELL": 0,
        "HOLD": 0,
    }

    for entry in _history.get(normalized_symbol, []):
        breakdown[entry["signal"]] += 1

    return breakdown


def get_average_confidence(symbol):
    # Kevin Ngo, 5/30/26 - calculate average confidence score
    # across all stored recommendations

    normalized_symbol = _normalize_symbol(symbol)

    history = _history.get(normalized_symbol, [])

    if not history:
        return 0.0

    total = sum(entry["confidence"] for entry in history)

    return round(total / len(history), 2)


def get_all_tracked_symbols():
    # Kevin Ngo, 5/30/26 - return all stock symbols currently
    # tracked by the signal history system

    return sorted(_history.keys())
